mapper.select:
SELECT * FROM notifications
WHERE user_id = #{userId}
  AND type = #{type}

      AND (last_event_at < #{cursorAt}
           OR (last_event_at = #{cursorAt} AND id < #{cursorId}))

ORDER BY last_event_at DESC, id DESC
LIMIT #{size}

mapper.update:
UPDATE notifications SET is_read = 0
WHERE user_id = #{userId}
  AND agg_key = #{aggKey}
  AND is_read = 1
